CREATE TYPE "ArtifactKind" AS ENUM ('OVERVIEW', 'FLASHCARDS', 'QUIZ', 'COMPARISON', 'EXTRACTION');
CREATE TYPE "ArtifactStatus" AS ENUM ('QUEUED', 'GENERATING', 'READY', 'FAILED', 'CANCELLED');
CREATE TABLE "folders" ("id" UUID NOT NULL, "user_id" UUID NOT NULL, "name" TEXT NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "folders_pkey" PRIMARY KEY ("id"));
CREATE TABLE "tags" ("id" UUID NOT NULL, "user_id" UUID NOT NULL, "name" TEXT NOT NULL, CONSTRAINT "tags_pkey" PRIMARY KEY ("id"));
CREATE TABLE "analysis_artifacts" ("id" UUID NOT NULL, "user_id" UUID NOT NULL, "kind" "ArtifactKind" NOT NULL, "status" "ArtifactStatus" NOT NULL DEFAULT 'QUEUED', "configuration" JSONB NOT NULL DEFAULT '{}', "result" JSONB, "prompt_version" TEXT NOT NULL DEFAULT 'v1', "error_code" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "analysis_artifacts_pkey" PRIMARY KEY ("id"));
CREATE TABLE "artifact_sources" ("artifact_id" UUID NOT NULL, "document_id" UUID NOT NULL, CONSTRAINT "artifact_sources_pkey" PRIMARY KEY ("artifact_id", "document_id"));
CREATE TABLE "document_tags" ("document_id" UUID NOT NULL, "tag_id" UUID NOT NULL, CONSTRAINT "document_tags_pkey" PRIMARY KEY ("document_id", "tag_id"));
CREATE TABLE "notes" ("id" UUID NOT NULL, "user_id" UUID NOT NULL, "document_id" UUID, "conversation_id" UUID, "content" TEXT NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "notes_pkey" PRIMARY KEY ("id"));
CREATE TABLE "bookmarks" ("id" UUID NOT NULL, "user_id" UUID NOT NULL, "message_id" UUID, "label" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "bookmarks_pkey" PRIMARY KEY ("id"));
CREATE TABLE "quiz_attempts" ("id" UUID NOT NULL, "artifact_id" UUID NOT NULL, "user_id" UUID NOT NULL, "score" INTEGER NOT NULL, "answers" JSONB NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "quiz_attempts_pkey" PRIMARY KEY ("id"));
ALTER TABLE "documents" ADD COLUMN "folder_id" UUID, ADD COLUMN "favorite" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "processing_jobs" ADD COLUMN "artifact_id" UUID;
CREATE UNIQUE INDEX "folders_user_id_name_key" ON "folders"("user_id", "name"); CREATE UNIQUE INDEX "tags_user_id_name_key" ON "tags"("user_id", "name"); CREATE INDEX "analysis_artifacts_user_id_kind_status_idx" ON "analysis_artifacts"("user_id", "kind", "status"); CREATE INDEX "notes_user_id_document_id_idx" ON "notes"("user_id", "document_id"); CREATE INDEX "bookmarks_user_id_created_at_idx" ON "bookmarks"("user_id", "created_at"); CREATE INDEX "quiz_attempts_user_id_artifact_id_idx" ON "quiz_attempts"("user_id", "artifact_id");
ALTER TABLE "folders" ADD CONSTRAINT "folders_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE; ALTER TABLE "tags" ADD CONSTRAINT "tags_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE; ALTER TABLE "documents" ADD CONSTRAINT "documents_folder_id_fkey" FOREIGN KEY ("folder_id") REFERENCES "folders"("id") ON DELETE SET NULL; ALTER TABLE "analysis_artifacts" ADD CONSTRAINT "analysis_artifacts_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE; ALTER TABLE "artifact_sources" ADD CONSTRAINT "artifact_sources_artifact_id_fkey" FOREIGN KEY ("artifact_id") REFERENCES "analysis_artifacts"("id") ON DELETE CASCADE; ALTER TABLE "artifact_sources" ADD CONSTRAINT "artifact_sources_document_id_fkey" FOREIGN KEY ("document_id") REFERENCES "documents"("id") ON DELETE CASCADE; ALTER TABLE "document_tags" ADD CONSTRAINT "document_tags_document_id_fkey" FOREIGN KEY ("document_id") REFERENCES "documents"("id") ON DELETE CASCADE; ALTER TABLE "document_tags" ADD CONSTRAINT "document_tags_tag_id_fkey" FOREIGN KEY ("tag_id") REFERENCES "tags"("id") ON DELETE CASCADE; ALTER TABLE "notes" ADD CONSTRAINT "notes_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE; ALTER TABLE "notes" ADD CONSTRAINT "notes_document_id_fkey" FOREIGN KEY ("document_id") REFERENCES "documents"("id") ON DELETE SET NULL; ALTER TABLE "bookmarks" ADD CONSTRAINT "bookmarks_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE; ALTER TABLE "quiz_attempts" ADD CONSTRAINT "quiz_attempts_artifact_id_fkey" FOREIGN KEY ("artifact_id") REFERENCES "analysis_artifacts"("id") ON DELETE CASCADE;
ALTER TABLE "processing_jobs" ADD CONSTRAINT "processing_jobs_artifact_id_fkey" FOREIGN KEY ("artifact_id") REFERENCES "analysis_artifacts"("id") ON DELETE CASCADE;
